        mac     x0,y1,a                 ; y = s + g*w
        move    #>$ffcb14,n5            ; AP5R 467, g=0.6
        move    y:(r5+n5),x0
        mpy     y0,x0,b       #>$4ccccd,y1; s = absorb * d; g
        move    b,x0
        mac     -x0,y1,a                ; w = x - g*s
        move    #>$ffcce7,n5
        move    a,y:(r5+n5)
        move    a,x0
        mac     x0,y1,b                 ; y = s + g*w
        move    #>$ffc856,n5            ; AP6R 701, g=0.6
        move    y:(r5+n5),x0
        mpy     y0,x0,a       #>$4ccccd,y1; s = absorb * d; g
        move    a,x0
        mac     -x0,y1,b                ; w = x - g*s
        move    #>$ffcb13,n5
        move    b,y:(r5+n5)
        move    b,x0
        mac     x0,y1,a                 ; y = s + g*w
