        move    a0,b
        lsr     b                       ; b1 = f << 15, non-negative; b2 is stale
        lua     (r5+n5),r4
        move    b1,y0                   ; f, the fraction toward the newer word
        move    y:(r4)+,b
        move    y:(r4),a
        sub     b,a
        move    a,x0
        mpy     y0,x0,a
        add     b,a
        move    a,x:(r7+$1d)            ; L has read it
; ---- output: BAL, WIDTH, makeup, MIX ----
        move    x:(r7+$20),b            ; wl = early + bal*(late - early)
        move    x:(r7+$22),a
        sub     b,a
        move    a,x0
        move    x:(r7+$43),y1
        mpy     x0,y1,a
        add     b,a
        move    a,x1
        move    x:(r7+$21),b            ; wr = early + bal*(late - early)
        move    x:(r7+$23),a
