        move    a,x0
        mpy     x0,y1,a
        add     b,a
        move    a,x:(r0)+
        move    x:(r7+$1e),x0
        move    x0,x:(r7+$1c)
        move    (r5)+
dv_end:
        nop     
        move    r5,x:(r7+$01)
        move    #>$ffffff,m4
        move    #>$ffffff,m5
        rts     

; k/127 of a knob word in a: x0 = w + w/127, saturated. Clobbers a, y1.
; After proc: dsp_asm cannot encode a backward bsr.
dv_q:
        and     #>$7f0000,a             ; an LFO leaves bits 8-15 set
        move    a1,x0
        move    #>$010204,y1            ; 1/127
        mpy     x0,y1,a
        add     x0,a
        move    a,x0                    ; 127 -> the largest word
